import { mkdir, mkdtemp, readdir, readFile, writeFile } from "node:fs/promises";
import { createRequire } from "node:module";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { beforeAll, describe, expect, it } from "vitest";
import { build } from "yaakdoc";
import type * as Engine from "../src/engine";

// The bundled engine that ships with the plugin (generated by scripts/prebuild.mjs).
const engine = createRequire(import.meta.url)("../generated/engine.cjs") as typeof Engine;

const FIXTURE = new URL("../../core/test/fixtures/current.json", import.meta.url);
const overrides = { pages: "per-request", base: "/docs/", environments: "public" } as const;

/** Content-hashed client file names differ between builds, so they're normalized. */
const normalize = (html: string) => html.replace(/client-[\w-]{8}\.(js|css)/g, "client-HASH.$1");

async function files(dir: string) {
  return (await readdir(dir, { recursive: true, withFileTypes: true }))
    .filter((entry) => entry.isFile())
    .map((entry) => join(entry.parentPath, entry.name).slice(dir.length + 1))
    .map((file) => normalize(file))
    .sort();
}

describe("built-in engine", () => {
  let dir: string;

  beforeAll(async () => {
    dir = await mkdtemp(join(tmpdir(), "yaakdoc-plugin-test-"));

    // Markdown pages (search is on by default, so the search index is compared too).
    const pagesDir = join(dir, "pages");
    await mkdir(join(pagesDir, "guides"), { recursive: true });
    await writeFile(join(pagesDir, "index.md"), "---\ntitle: Introduction\n---\n\nStart here.\n");
    await writeFile(join(pagesDir, "guides", "auth.md"), "# Authentication\n\n## Tokens\n");

    const exportData = JSON.parse(await readFile(FIXTURE, "utf8"));

    await engine.buildSite({
      exportData,
      cwd: dir,
      overrides: { ...overrides, pagesDir, outDir: join(dir, "plugin") },
    });

    await build({
      cwd: dir,
      overrides: { ...overrides, pagesDir, export: FIXTURE.pathname, outDir: join(dir, "cli") },
    });
  });

  it("builds the same site as yaakdoc build", async () => {
    const plugin = join(dir, "plugin");
    const cli = join(dir, "cli");
    const list = await files(cli);

    expect(await files(plugin)).toEqual(list);
    expect(list).toEqual(
      expect.arrayContaining(["guides/auth/index.html", "_yaakdoc/search.json"]),
    );

    for (const file of list.filter((name) => /\.(html|md|txt|json)$/.test(name))) {
      const [a, b] = await Promise.all([
        readFile(join(plugin, file), "utf8"),
        readFile(join(cli, file), "utf8"),
      ]);

      expect(normalize(a), file).toBe(normalize(b));
    }
  });

  it("links custom CSS after the theme's styles", async () => {
    const css = join(dir, "brand.css");

    await writeFile(css, ".brand { color: teal; }");

    await engine.buildSite({
      exportData: JSON.parse(await readFile(FIXTURE, "utf8")),
      cwd: dir,
      overrides: { base: "/docs/", branding: { customCss: css }, outDir: join(dir, "custom") },
    });

    const html = await readFile(join(dir, "custom", "index.html"), "utf8");
    const links = [...html.matchAll(/<link rel="stylesheet" href="([^"]+)"/g)].map((m) => m[1]!);

    expect(links).toHaveLength(2);
    expect(links[1]).toMatch(/^\/docs\/_yaakdoc\/brand-\w{8}\.css$/);
    expect(await readFile(join(dir, "custom", links[1]!.slice("/docs/".length)), "utf8")).toBe(
      ".brand { color: teal; }",
    );
  });

  it("refuses themes that aren't built in", async () => {
    await expect(
      engine.buildSite({
        exportData: JSON.parse(await readFile(FIXTURE, "utf8")),
        cwd: dir,
        overrides: { theme: "./my-theme", outDir: join(dir, "other") },
      }),
    ).rejects.toMatchObject({ name: "ExternalThemeError", theme: join(dir, "my-theme") });
  });
});
